import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
REBALANCE_DAYS = 10
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
last_decision = None


def rank(values, direction=1):
    finite = [(s, direction * float(v)) for s, v in values.items() if np.isfinite(v)]
    out = {s: 0.5 for s in UNIVERSE}
    if finite:
        finite.sort(key=lambda x: x[1])
        n = len(finite)
        for i, (s, _) in enumerate(finite):
            out[s] = (i + 1.0) / n
    return out


def project(raw):
    # Smooth positive scores, then enforce a complete 15-asset target.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    w = {s: v / z for s, v in w.items()}
    # Iterative clipping and redistribution.
    for _ in range(20):
        low = [s for s in UNIVERSE if w[s] < MIN_WEIGHT]
        high = [s for s in UNIVERSE if w[s] > MAX_WEIGHT]
        if not low and not high:
            break
        fixed = {s: MIN_WEIGHT for s in low}
        fixed.update({s: MAX_WEIGHT for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        base = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, rem * w[s] / base) for s in UNIVERSE}
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        ensemble = json.loads(ENSEMBLE_PATH.read_text())
        selected = ensemble.get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    account = get_account_dict()
    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=90)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        ret = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        data[symbol] = (close, high, low, ret, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision = max(v[4] for v in data.values())
    if last_decision is not None:
        try:
            elapsed = (np.datetime64(decision) - np.datetime64(last_decision)) / np.timedelta64(1, "D")
            if elapsed < REBALANCE_DAYS:
                return
        except Exception:
            return

    raw_factors = {item["factor_id"]: {} for item in selected}
    five_day = {}
    for s, (c, h, l, r, _) in data.items():
        daily_clv = (2*c - h - l) / np.maximum(h-l, 1e-12)
        five_day[s] = c[-1] / max(c[-6], 1e-12) - 1.0
        for item in selected:
            fid = item["factor_id"]
            if fid == "miner_3_clv_1d":
                raw_factors[fid][s] = np.mean(daily_clv[-3:])
            elif fid == "peer_median_leadlag_5d":
                raw_factors[fid][s] = five_day[s]
            elif fid == "short_term_reversal_5d":
                raw_factors[fid][s] = -np.mean(r[-5:])
            elif fid == "miner_2_risk_adjusted_momentum_20d":
                vol = max(float(np.std(r[-20:])), 0.008)
                raw_factors[fid][s] = (c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01)

    # Peer factor is demeaned cross-sectionally; all directions come from the ensemble.
    if "peer_median_leadlag_5d" in raw_factors and five_day:
        med = float(np.median(list(five_day.values())))
        raw_factors["peer_median_leadlag_5d"] = {s: v-med for s, v in five_day.items()}
    scores = {s: 0.5 for s in UNIVERSE}
    for item in selected:
        fid, weight, direction = item["factor_id"], float(item["weight"]), int(item.get("direction", 1))
        rr = rank(raw_factors.get(fid, {}), direction)
        for s in UNIVERSE:
            scores[s] += weight * (rr[s] - 0.5)

    # Bullish but medium-high risk: retain diversification and volatility-aware sizing.
    vols = {}
    for s, (_, _, _, r, _) in data.items():
        vols[s] = max(float(np.std(r[-20:])), 0.008)
    median_vol = float(np.median(list(vols.values())))
    raw = {s: max(0.02, scores[s]) / (0.80 + 0.20 * vols.get(s, median_vol) / median_vol) for s in UNIVERSE}
    # If broad trend breaks, shift, rather than reduce, exposure to defensive tradables.
    if "SPX" in data:
        c = data["SPX"][0]
        if c[-1] < c[-21] and c[-1] < c[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                raw[s] *= 1.35
            for s in ("BTC", "ETH", "WTI"):
                raw[s] *= 0.65
    weights = project(raw)
    vals = np.array([scores[s] for s in UNIVERSE], dtype=float)
    mean, std = float(np.mean(vals)), max(float(np.std(vals)), 1e-12)
    forecast_returns = {s: 0.01 * (scores[s] - mean) / std for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns,
                         factor_ids=[str(x["factor_id"]) for x in selected], horizon_days=10)
    last_decision = decision

