def cross_asset_strategy():
    global last_decision
    try:
        ensemble = json.loads(ENSEMBLE_PATH.read_text())
        selected = ensemble.get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    account = get_account_dict()
    # The account call intentionally verifies the live contract without using cash as an asset.
    if set(UNIVERSE) != set(account.get("watch_list", UNIVERSE)):
        return
