                raw_factors[fid][s] = (c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01)
            elif fid == "miner_2_20270225_cross_asset_residual_reversal_3d":
                raw_factors[fid][s] = -(ret3[s] - peer3)

