        fid = x["factor_id"]
        rr = rank(raw_factors.get(fid, {}), int(x.get("direction", 1)))
        for s in UNIVERSE:
            scores[s] += float(x["weight"]) * (rr[s] - 0.5)

    vols = {s: max(float(np.std(v[3][-20:])), 0.008) for s, v in data.items()}
    medvol = float(np.median(list(vols.values())))
    raw = {s: max(0.02, scores[s]) / (0.80 + 0.20 * vols.get(s, medvol) / medvol) for s in UNIVERSE}
    # Medium-high risk bullish regime: retain breadth, and use defensive tradables only if trend breaks.
    if "SPX" in data and data["SPX"][0][-1] < data["SPX"][0][-21] and data["SPX"][0][-1] < data["SPX"][0][-6]:
        for s in ("XAU", "US10Y", "CN10Y"):
            raw[s] *= 1.35
        for s in ("BTC", "ETH", "WTI"):
            raw[s] *= 0.65
    weights = project(raw)
    sv = np.array([scores[s] for s in UNIVERSE], dtype=float)
    mean, std = float(np.mean(sv)), max(float(np.std(sv)), 1e-12)
    forecast_returns = {s: float(0.01 * (scores[s] - mean) / std) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns,
                         factor_ids=[str(x["factor_id"]) for x in selected], horizon_days=10)
    last_decision = decision

