UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
REBALANCE_DAYS = 10
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
last_decision = None


def percentile(values, direction=1):
    good = [(s, direction * float(v)) for s, v in values.items() if np.isfinite(v)]
    out = {s: 0.5 for s in UNIVERSE}
    good.sort(key=lambda z: z[1])
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n
    return out


def bounded_weights(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    total = sum(w.values()) or 1.0
    w = {s: x / total for s, x in w.items()}
    # Iterative water-filling preserves a complete, long-only, full-investment vector.
    for _ in range(20):
        low = [s for s in UNIVERSE if w[s] < MIN_WEIGHT]
        high = [s for s in UNIVERSE if w[s] > MAX_WEIGHT]
        if not low and not high:
            break
        fixed = {s: MIN_WEIGHT for s in low}
        fixed.update({s: MAX_WEIGHT for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        remainder = max(0.0, 1.0 - sum(fixed.values()))
        scale = remainder / (sum(w[s] for s in free) or 1.0)
        w = {s: fixed.get(s, w[s] * scale) for s in UNIVERSE}
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    account = get_account_dict()
    if set(account.get("watch_list", UNIVERSE)) != set(UNIVERSE):
        return

    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        daily = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        data[symbol] = (close, high, low, daily, str(df.iloc[-1]["date"]))
