                return
        except Exception:
            return

    ret5 = {s: x[0][-1] / max(x[0][-6], 1e-12) - 1.0 for s, x in data.items()}
    ret3 = {s: x[0][-1] / max(x[0][-4], 1e-12) - 1.0 for s, x in data.items()}
