    for f in selected:
        ranks = percentile(factors.get(f["factor_id"], {}), int(f.get("direction", 1)))
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (ranks[s] - 0.5)

    vol = {s: max(float(np.std(x[3][-20:])), 0.008) for s, x in data.items()}
    median_vol = float(np.median(list(vol.values())))
    raw = {s: max(0.02, score[s]) / (0.80 + 0.20 * vol.get(s, median_vol) / median_vol) for s in UNIVERSE}

    # Bullish but high-risk: use volatility control; on a confirmed SPX break, rotate
    # toward tradable defensives rather than creating a cash sleeve.
    if "SPX" in data and data["SPX"][0][-1] < data["SPX"][0][-21] and data["SPX"][0][-1] < data["SPX"][0][-6]:
