import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
REBALANCE_DAYS = 10
last_decision = None


def rank_factor(values):
    good = [(s, float(v)) for s, v in values.items() if np.isfinite(v)]
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    good.sort(key=lambda z: z[1])
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    total = sum(w.values()) or 1.0
    w = {s: v / total for s, v in w.items()}
    # Iterative water filling enforces a complete, long-only, full-investment vector.
    for _ in range(20):
        low = [s for s in UNIVERSE if w[s] < MIN_WEIGHT]
        high = [s for s in UNIVERSE if w[s] > MAX_WEIGHT]
        if not low and not high:
            break
        fixed = {s: MIN_WEIGHT for s in low}
        fixed.update({s: MAX_WEIGHT for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        remainder = max(0.0, 1.0 - sum(fixed.values()))
        scale = remainder / (sum(w[s] for s in free) or 1.0)
        w = {s: fixed.get(s, w[s] * scale) for s in UNIVERSE}
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    expected = {
        "miner_3_clv_1d", "peer_median_leadlag_5d",
        "miner_2_risk_adjusted_momentum_20d",
        "miner_1_20270422_dispersion_conditioned_reversal_1d",
        "miner_2_vix_regime_reversal_1d",
    }
    if not selected or {str(f.get("factor_id")) for f in selected} != expected:
        return
    account = get_account_dict()
    if set(account.get("watch_list", UNIVERSE)) != set(UNIVERSE):
        return

    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=130)
        if df is None or len(df) < 65:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        try:
            o, c, h, l = [np.asarray(df[x], dtype=float) for x in ("open", "close", "high", "low")]
        except Exception:
            continue
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (o, c, h, l, r, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision = max(x[5] for x in data.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < REBALANCE_DAYS:
                return
        except Exception:
            return

    ret5 = {s: x[1][-1] / max(x[1][-6], 1e-12) - 1.0 for s, x in data.items()}
    median5 = float(np.median(list(ret5.values())))
    daily = {s: x[4][-1] for s, x in data.items()}
    dispersion = float(np.std(list(daily.values())))
    hist = []
    for k in range(2, min(62, len(next(iter(data.values()))[4]))):
        vals = [x[4][-k] for x in data.values() if len(x[4]) >= k]
        if len(vals) >= 8:
            hist.append(float(np.std(vals)))
    disp_med = float(np.median(hist)) if hist else max(dispersion, 1e-8)
    disp_amp = float(np.clip(dispersion / max(disp_med, 1e-8) - 1.0, -0.5, 1.5))

    # VIX is observation-only. Its latest completed value gates a one-day reversal;
    # high VIX makes the reversal more selective rather than changing factor direction.
    vix = get_index_daily_data(symbol="VIX", days=35)
    vix_level, vix_base = 0.0, 0.0
    if vix is not None and len(vix) >= 22:
        vc = np.asarray(vix.sort_values("date")["close"], dtype=float)
        vix_level = float(vc[-1])
        vix_base = float(np.median(vc[-22:-1]))
    shock = float(np.clip(vix_level / max(vix_base, 1e-8) - 1.0, -0.5, 1.5)) if vix_base else 0.0

    factors = {str(f["factor_id"]): {} for f in selected}
    for s, (o, c, h, l, r, _) in data.items():
        factors["miner_3_clv_1d"][s] = (2.0 * c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12)
        factors["peer_median_leadlag_5d"][s] = ret5[s] - median5
        factors["miner_2_risk_adjusted_momentum_20d"][s] = (c[-1] / max(c[-21], 1e-12) - 1.0) / max(float(np.std(r[-20:])), 0.008)
        factors["miner_1_20270422_dispersion_conditioned_reversal_1d"][s] = -(c[-1] / max(c[-4], 1e-12) - 1.0) * (1.0 + 0.8 * disp_amp)
        factors["miner_2_vix_regime_reversal_1d"][s] = -(c[-1] / max(o[-1], 1e-12) - 1.0) * (1.0 + 0.5 * max(shock, 0.0))

    score = {s: 0.5 for s in UNIVERSE}
    for f in selected:
        rr = rank_factor(factors[str(f["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - 0.5)
    vol = {s: max(float(np.std(x[4][-20:])), 0.008) for s, x in data.items()}
    medvol = float(np.median(list(vol.values())))
    raw = {s: max(0.02, score[s]) / (0.80 + 0.20 * vol.get(s, medvol) / medvol) for s in UNIVERSE}
    if "SPX" in data and data["SPX"][1][-1] < data["SPX"][1][-21] and data["SPX"][1][-1] < data["SPX"][1][-6]:
        for s in ("XAU", "US10Y", "CN10Y"):
            raw[s] *= 1.35
        for s in ("BTC", "ETH", "WTI"):
            raw[s] *= 0.65
    weights = bounded_weights(raw)
    vals = np.asarray([score[s] for s in UNIVERSE], dtype=float)
    z = max(float(np.std(vals)), 1e-12)
    forecast_returns = {s: float(0.01 * (score[s] - float(np.mean(vals))) / z) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns,
                         factor_ids=[str(f["factor_id"]) for f in selected], horizon_days=10)
    last_decision = decision

