import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
last_decision = None


def rank_map(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def project_weights(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    w = {s: v / (sum(w.values()) or 1.0) for s, v in w.items()}
    # Projection is deliberately bounded and preserves a complete, cash-free vector.
    for _ in range(40):
        low = {s for s in UNIVERSE if w[s] < MIN_WEIGHT}
        high = {s for s in UNIVERSE if w[s] > MAX_WEIGHT}
        fixed = {s: MIN_WEIGHT for s in low}
        fixed.update({s: MAX_WEIGHT for s in high})
        if not fixed:
            break
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        scale = rem / (sum(w[s] for s in free) or 1.0)
        w = {s: fixed.get(s, w[s] * scale) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}


def macro(symbol, days=40):
    df = get_index_daily_data(symbol=symbol, days=days)
    if df is None or len(df) < 2:
        return None
    return np.asarray(df.sort_values("date")["close"], dtype=float)


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    ids = [str(x.get("factor_id")) for x in selected]
    needed = {"miner_3_clv_1d", "peer_median_leadlag_5d",
              "miner_2_risk_adjusted_momentum_20d", "miner_2_vix_regime_reversal_1d",
              "miner_3_consensus_reversal_3d", "miner_2_breadth_conditioned_reversal_1d",
              "miner_2_usdjpy_conditioned_reversal_1d"}
    if set(ids) != needed or any(int(x.get("direction", 1)) != 1 for x in selected):
        return
    account = get_account_dict()
    if set(account.get("watch_list", UNIVERSE)) != set(UNIVERSE):
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=130)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date")
        o, c = np.asarray(df.open, float), np.asarray(df.close, float)
        h, l = np.asarray(df.high, float), np.asarray(df.low, float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (o, c, h, l, r, str(df.iloc[-1].date))
    if len(data) < 12:
        return
    decision = max(v[5] for v in data.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            return

    ret3 = {s: x[1][-1] / max(x[1][-4], 1e-12) - 1 for s, x in data.items()}
    ret5 = {s: x[1][-1] / max(x[1][-6], 1e-12) - 1 for s, x in data.items()}
    median5 = float(np.median(list(ret5.values())))
    breadth_weak = sum(v < 0 for v in ret3.values()) / len(ret3) >= 0.60
    vix, usdjpy = macro("VIX"), macro("USDJPY")
    shock = 0.0 if vix is None or len(vix) < 22 else float(np.clip(vix[-1] / max(np.median(vix[-22:-1]), 1e-9) - 1, -.5, 1.5))
    jpy_move = 0.0 if usdjpy is None else float(usdjpy[-1] / max(usdjpy[-6], 1e-9) - 1)
    f = {k: {} for k in needed}
    for s, (o, c, h, l, r, _) in data.items():
        day = c[-1] / max(o[-1], 1e-12) - 1
        f["miner_3_clv_1d"][s] = (2*c[-1]-h[-1]-l[-1]) / max(h[-1]-l[-1], 1e-12)
        f["peer_median_leadlag_5d"][s] = ret5[s] - median5
        f["miner_2_risk_adjusted_momentum_20d"][s] = (c[-1]/max(c[-21], 1e-12)-1) / max(float(np.std(r[-20:])), .008)
        f["miner_2_vix_regime_reversal_1d"][s] = -day * (1.0 + .5*max(shock, 0.0))
        f["miner_3_consensus_reversal_3d"][s] = -ret3[s]
        f["miner_2_breadth_conditioned_reversal_1d"][s] = -day if breadth_weak else 0.0
        f["miner_2_usdjpy_conditioned_reversal_1d"][s] = -ret3[s] * (1.0 + min(abs(jpy_move)*5.0, 1.0))

    score = {s: 0.5 for s in UNIVERSE}
    for item in selected:
        rr = rank_map(f[item["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(item["weight"]) * (rr[s] - 0.5)
    vol = {s: max(float(np.std(x[4][-20:])), .008) for s, x in data.items()}
    medvol = float(np.median(list(vol.values())))
    raw = {s: max(.02, score[s]) / (.8 + .2 * vol.get(s, medvol) / medvol) for s in UNIVERSE}
    spx = data.get("SPX")
    if spx is not None and (spx[1][-1] < spx[1][-21] or shock > .25):
        for s in ("XAU", "US10Y", "CN10Y"): raw[s] *= 1.30
        for s in ("BTC", "ETH", "WTI"): raw[s] *= .70
    weights = project_weights(raw)
    a = np.asarray([score[s] for s in UNIVERSE])
    scale = max(float(np.std(a)), 1e-9)
    forecast = {s: float(.01 * (score[s] - float(np.mean(a))) / scale) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = decision

