ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
MIN_W, MAX_W = 0.015, 0.16
last_decision = None


def ranks(vals):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    if good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(50):
        total = sum(w.values()) or 1.0
        w = {s: x / total for s, x in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        fixed = {s: MIN_W for s in low}
        fixed.update({s: MAX_W for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        remain = max(0.0, 1.0 - sum(fixed.values()))
        z = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, w[s] * remain / z) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}


def macro(symbol, days=70):
    d = get_index_daily_data(symbol=symbol, days=days)
    if d is None or len(d) < 2:
        return None
    return np.asarray(d.sort_values("date")["close"], dtype=float)


