    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
MIN_W, MAX_W = 0.015, 0.16
last_decision = None


def rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(60):
        z = sum(w.values()) or 1.0
        w = {s: x / z for s, x in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        fixed = {s: MIN_W for s in low}
        fixed.update({s: MAX_W for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        remain = 1.0 - sum(fixed.values())
        fz = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, w[s] * remain / fz) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}


def series(symbol, days=80):
    d = get_index_daily_data(symbol=symbol, days=days)
    if d is None or len(d) < 2:
        return None
    return np.asarray(d.sort_values("date")["close"], dtype=float)


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x.get("weight", 0.0)) for x in selected) - 1.0) > 1e-6:
        return
    ids = [str(x["factor_id"]) for x in selected]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in selected}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in selected}
    account = get_account_dict()
    if set(account.get("watch_list", UNIVERSE)) != set(UNIVERSE):
        return

    data = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=170)
        if d is None or len(d) < 65:
            continue
        d = d.sort_values("date")
        o, c = np.asarray(d["open"], float), np.asarray(d["close"], float)
        h, l = np.asarray(d["high"], float), np.asarray(d["low"], float)
        r = np.diff(c) / np.maximum(c[:-1], 1e-12)
        data[s] = (o, c, h, l, r, str(d.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision = max(x[5] for x in data.values())
    if last_decision is not None and decision != last_decision:
        try:
            if np.busday_count(np.datetime64(last_decision), np.datetime64(decision)) < 10:
                return
        except Exception:
            return
    if decision == last_decision:
        return

    ret3 = {s: v[1][-1] / max(v[1][-4], 1e-12) - 1 for s, v in data.items()}
    ret5 = {s: v[1][-1] / max(v[1][-6], 1e-12) - 1 for s, v in data.items()}
    peer_median = float(np.median(list(ret5.values())))
    breadth = sum(x < 0 for x in ret3.values()) / len(ret3)
    vix = series("VIX")
    stress = 0.0 if vix is None or len(vix) < 22 else float(np.clip(vix[-1] / max(np.median(vix[-22:-1]), 1e-12) - 1, -.5, 1.5))
    factors = {k: {} for k in ids}
    for s, (o, c, h, l, r, _) in data.items():
        vol20 = max(float(np.std(r[-20:])), .008)
        prior = c[-61:-1]
        raw = {
            "peer_median_leadlag_5d": ret5[s] - peer_median,
            "miner_2_risk_adjusted_momentum_20d": (c[-1] / max(c[-21], 1e-12) - 1) / vol20,
            "range_recovery_60d": ((c[-1] - np.min(prior)) / max(np.max(prior) - np.min(prior), 1e-12)) / vol20,
            "miner_3_clv_1d": (2*c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12),
            "miner_1_close_reversal_2d": -(c[-1] / max(c[-3], 1e-12) - 1),
            "miner_2_vix_stress_reversal_3d": -ret3[s] * (1.0 + max(stress, 0.0)),
            "miner_3_consensus_reversal_3d": -ret3[s],
        }
        for k in ids:
            factors[k][s] = directions[k] * raw.get(k, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for k in ids:
        rk = rank(factors[k])
        for s in UNIVERSE:
            score[s] += weights[k] * (rk[s] - 0.5)
    vol = {s: max(float(np.std(data[s][4][-20:])), .008) for s in data}
    medvol = float(np.median(list(vol.values())) or .008)
    raw_weight = {s: max(.02, score[s]) / (.85 + .15 * vol.get(s, medvol) / medvol) for s in UNIVERSE}
    spx = data.get("SPX")
    risk_off = stress > .25 or breadth >= .60 or (spx is not None and spx[1][-1] < spx[1][-21])
    if risk_off:
        for s in ("XAU", "US10Y", "CN10Y"):
            raw_weight[s] *= 1.50
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            raw_weight[s] *= .60
    target = bounded(raw_weight)
    center = float(np.mean(list(score.values())))
    scale = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - center) / scale) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = decision
