        for i, (s, _) in enumerate(good): out[s] = (i + 1.0) / n
    return out

def bounded(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    # Iterative projection keeps every tradable asset funded and sums exactly to one.
    for _ in range(30):
        z = sum(w.values()) or 1.0
        w = {s: v / z for s, v in w.items()}
        low = {s for s in UNIVERSE if w[s] < MIN_W}
        high = {s for s in UNIVERSE if w[s] > MAX_W}
        fixed = {s: MIN_W for s in low}
        fixed.update({s: MAX_W for s in high})
        if not fixed: break
        free = [s for s in UNIVERSE if s not in fixed]
        remain = 1.0 - sum(fixed.values())
        zf = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, w[s] * remain / zf) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}

def factor_key(fid):
    # Ensemble IDs are versioned; these canonical suffixes define the implementation.
    for key in ("peer_median_leadlag_5d", "risk_adjusted_momentum_20d",
                "breadth_conditioned_reversal_1d", "range_recovery_60d",
                "beta_neutral_reversal_5d", "clv_1d", "overnight_gap_reversal_1d",
                "vix_regime_reversal_1d"):
        if key in fid: return key
    return fid

