import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

U = ["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX","XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None

def rank(values):
    a = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in U}
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.0) / max(len(a), 1)
    return out

def bounded(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in U}
    for _ in range(30):
        z = sum(w.values()) or 1.0
        w = {s: x / z for s, x in w.items()}
        fixed = {s: 0.015 for s in U if w[s] < 0.015}
        fixed.update({s: 0.16 for s in U if w[s] > 0.16})
        if not fixed:
            break
        free = [s for s in U if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        z = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, w[s] * rem / z) for s in U}
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in U}

def vix_series():
    x = get_index_daily_data(symbol="VIX", days=90)
    if x is None:
        return None
    return np.asarray(x.sort_values("date")["close"], dtype=float)

@register_hook
def strategy():
    global last_decision
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(x.get("weight", 0)) for x in factors) - 1.0) > 1e-6:
        return
    ids = [str(x["factor_id"]) for x in factors]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in factors}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in factors}
    account = get_account_dict()
    if set(account.get("watch_list", U)) != set(U):
        return
    data = {}
    for s in U:
        x = get_stock_daily_data(symbol=s, days=180)
        if x is None or len(x) < 65:
            return
        x = x.sort_values("date")
        data[s] = (np.asarray(x["open"], float), np.asarray(x["close"], float),
                   np.asarray(x["high"], float), np.asarray(x["low"], float), str(x.iloc[-1]["date"]))
    date = max(x[4] for x in data.values())
    if last_decision is not None:
        try:
            if date == last_decision or np.busday_count(np.datetime64(last_decision), np.datetime64(date)) < 10:
                return
        except Exception:
            return
    ret = {n: {s: data[s][1][-1] / max(data[s][1][-(n+1)], 1e-12) - 1 for s in U} for n in (1, 3, 5)}
    peer = float(np.median(list(ret[5].values())))
    breadth = sum(v < 0 for v in ret[3].values()) / len(U)
    vx = vix_series()
    stress = 0.0 if vx is None or len(vx) < 22 else float(np.clip(vx[-1] / max(np.median(vx[-22:-1]), 1e-12) - 1, -.5, 1.5))
    vol = {s: max(float(np.std(np.diff(data[s][1]) / np.maximum(data[s][1][:-1], 1e-12)[-20:])), .008) for s in U}
    median_vol = float(np.median(list(vol.values())))
    raw_signals = {i: {} for i in ids}
    for s in U:
        o, c, h, l, _ = data[s]
        one = ret[1][s]
        rr = np.diff(c) / np.maximum(c[:-1], 1e-12)
        p = c[-61:-1]
        rng = max(float(np.max(p) - np.min(p)), 1e-12)
        rank_vol = vol[s] / max(median_vol, 1e-12)
        q = {
            "peer_median_leadlag_5d": ret[5][s] - peer,
            "risk_adjusted_momentum_20d": (c[-1] / max(c[-21], 1e-12) - 1) / vol[s],
            "breadth_conditioned_reversal_1d": -one * (1 + .5 * max(0, breadth - .5)),
            "range_recovery_60d": (c[-1] - min(p)) / rng,
            "beta_neutral_reversal_5d": -(ret[5][s] - peer),
            "clv_1d": (2*c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12),
            "overnight_gap_reversal_1d": -(o[-1] / max(c[-2], 1e-12) - 1),
            "vix_regime_reversal_1d": -one * (1 + max(0, stress)),
            "vix_high_rankvol_reversal_1d": -rank_vol if stress > 0 else 0.0,
        }
        for fid in ids:
            suffix = fid.split("_", 3)[-1]
            raw_signals[fid][s] = directions[fid] * q.get(suffix, 0.0)
    score = {s: .5 for s in U}
    for fid in ids:
        z = rank(raw_signals[fid])
        for s in U:
            score[s] += weights[fid] * (z[s] - .5)
    risk = stress > .25 or breadth >= .6 or data["SPX"][1][-1] < data["SPX"][1][-21]
    raw = {s: max(.02, score[s]) / (.85 + .15 * vol[s] / max(median_vol, 1e-12)) for s in U}
    if risk:
        for s in ("XAU", "US10Y", "CN10Y"):
            raw[s] *= 1.5
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            raw[s] *= .6
    target = bounded(raw)
    mean_score = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - mean_score) / sd) for s in U}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = date

