            "risk_adjusted_momentum_20d": (c[-1] / max(c[-21], 1e-12) - 1) / vol[s],
            "breadth_conditioned_reversal_1d": -one * (1 + .5 * max(0, breadth - .5)),
            "range_recovery_60d": (c[-1] - min(p)) / rng,
