import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
          "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def cross_rank(values):
    finite = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(finite):
        out[s] = (i + 1.0) / max(1, len(finite))
    return out


def bounded_weights(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in ASSETS}
    for _ in range(40):
        total = sum(w.values()) or 1.0
        w = {s: x / total for s, x in w.items()}
        fixed = {s: 0.015 for s in ASSETS if w[s] < 0.015}
        fixed.update({s: 0.16 for s in ASSETS if w[s] > 0.16})
        if not fixed:
            break
        free = [s for s in ASSETS if s not in fixed]
        remainder = 1.0 - sum(fixed.values())
        free_total = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, w[s] * remainder / free_total) for s in ASSETS}
    total = sum(w.values()) or 1.0
    return {s: w[s] / total for s in ASSETS}


def vix_stress():
    x = get_index_daily_data(symbol="VIX", days=90)
    if x is None or len(x) < 22:
        return 0.0
    c = np.asarray(x.sort_values("date")["close"], dtype=float)
    return float(np.clip(c[-1] / max(np.median(c[-22:-1]), 1e-12) - 1.0, -0.5, 1.5))


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f.get("weight", 0.0)) for f in selected) - 1.0) > 1e-6:
        return
    factor_ids = [str(f["factor_id"]) for f in selected]
    factor_weights = {str(f["factor_id"]): float(f["weight"]) for f in selected}
    directions = {str(f["factor_id"]): int(f.get("direction", 1)) for f in selected}
    suffix = {fid: fid.split("_", 3)[-1] for fid in factor_ids}

    account = get_account_dict()
    if set(account.get("watch_list", ASSETS)) != set(ASSETS):
        return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 65:
            return
        d = d.sort_values("date")
        data[s] = {k: np.asarray(d[k], dtype=float) for k in ("open", "close", "high", "low")}
        data[s]["date"] = str(d.iloc[-1]["date"])
    decision_date = max(data[s]["date"] for s in ASSETS)
    if last_date is not None:
        try:
            if decision_date == last_date or np.busday_count(np.datetime64(last_date), np.datetime64(decision_date)) < 10:
                return
        except Exception:
            return

    returns = {n: {s: data[s]["close"][-1] / max(data[s]["close"][-n-1], 1e-12) - 1.0 for s in ASSETS}
               for n in (1, 3, 5)}
    peer_median = float(np.median(list(returns[5].values())))
    breadth = sum(v < 0 for v in returns[3].values()) / len(ASSETS)
    stress = vix_stress()
    vol = {}
    for s in ASSETS:
        c = data[s]["close"]
        r = np.diff(c) / np.maximum(c[:-1], 1e-12)
        vol[s] = max(float(np.std(r[-20:])), 0.008)
    median_vol = float(np.median(list(vol.values())))

    signals = {fid: {} for fid in factor_ids}
    for s in ASSETS:
        o, c, h, l = (data[s][k] for k in ("open", "close", "high", "low"))
        one = returns[1][s]
        look = c[-61:-1]
        lo, hi = float(np.min(look)), float(np.max(look))
        rank_vol = vol[s] / max(median_vol, 1e-12)
        q = {
            "peer_median_leadlag_5d": returns[5][s] - peer_median,
            "risk_adjusted_momentum_20d": (c[-1] / max(c[-21], 1e-12) - 1.0) / vol[s],
            "vix_regime_reversal_1d": -one * (1.0 + max(0.0, stress)),
            "beta_neutral_reversal_5d": -(returns[5][s] - peer_median),
            "breadth_conditioned_reversal_1d": -one * (1.0 + 0.5 * max(0.0, breadth - 0.5)),
            "clv_1d": (2.0 * c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12),
            "overnight_gap_reversal_1d": -(o[-1] / max(c[-2], 1e-12) - 1.0),
            "vix_high_rankvol_reversal_1d": -rank_vol if stress > 0 else 0.0,
        }
        for fid in factor_ids:
            signals[fid][s] = directions[fid] * q.get(suffix[fid], 0.0)

    score = {s: 0.5 for s in ASSETS}
    for fid in factor_ids:
        ranked = cross_rank(signals[fid])
        for s in ASSETS:
            score[s] += factor_weights[fid] * (ranked[s] - 0.5)
    raw = {s: max(0.02, score[s]) / (0.85 + 0.15 * vol[s] / max(median_vol, 1e-12)) for s in ASSETS}
    risk_off = stress > 0.25 or breadth >= 0.6 or returns[1]["SPX"] < 0
    if risk_off:
        for s in ("XAU", "US10Y", "CN10Y"):
            raw[s] *= 1.5
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            raw[s] *= 0.6
    target = bounded_weights(raw)
    mean_score, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast_returns = {s: float(0.01 * (score[s] - mean_score) / sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    last_date = decision_date

