import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None

def ranks(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    if not good: return out
    for i, (s, _) in enumerate(good): out[s] = (i + 1.) / len(good)
    return out

def bounded(raw):
    w = {s: max(.015, min(.16, float(raw.get(s, 0)))) for s in ASSETS}
    # Iterative capped simplex projection, preserving full investment.
    for _ in range(20):
        z = sum(w.values())
        if abs(z - 1.) < 1e-10: break
        free = [s for s in ASSETS if .015 < w[s] < .16]
        if not free: break
        delta = (1. - z) / len(free)
        for s in free: w[s] = max(.015, min(.16, w[s] + delta))
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}

def vix_stress():
    d = get_index_daily_data(symbol="VIX", days=90)
    if d is None or len(d) < 22: return 0.
    c = np.asarray(d.sort_values("date")["close"], float)
    return float(np.clip(c[-1] / max(np.median(c[-22:-1]), 1e-9) - 1., -.5, 1.5))

@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text())["selected_factors"][:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.) > 1e-6:
        return
    ids = [str(x["factor_id"]) for x in selected]
    fw = {str(x["factor_id"]): float(x["weight"]) for x in selected}
    direction = {str(x["factor_id"]): int(x.get("direction", 1)) for x in selected}
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS): return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 65: return
        d = d.sort_values("date")
        data[s] = {k: np.asarray(d[k], float) for k in ("open", "close", "high", "low")}
        data[s]["date"] = str(d.iloc[-1]["date"])
    dt = max(data[s]["date"] for s in ASSETS)
    if last_date is not None:
        try:
            if dt == last_date or np.busday_count(np.datetime64(last_date), np.datetime64(dt)) < 10: return
        except Exception: return

    ret1 = {s: data[s]["close"][-1] / max(data[s]["close"][-2], 1e-12) - 1. for s in ASSETS}
    ret5 = {s: data[s]["close"][-1] / max(data[s]["close"][-6], 1e-12) - 1. for s in ASSETS}
    med5 = float(np.median(list(ret5.values())))
    breadth = sum(x < 0 for x in ret5.values()) / len(ASSETS)
    stress = vix_stress()
    vol = {}
    for s in ASSETS:
        c = data[s]["close"]
        vol[s] = max(float(np.std(np.diff(c[-21:]) / np.maximum(c[-21:-1], 1e-12))), .008)
    medvol = max(float(np.median(list(vol.values()))), 1e-9)
    scores = {fid: {} for fid in ids}
    for s in ASSETS:
        o, c, h, l = (data[s][k] for k in ("open", "close", "high", "low"))
        gap = o[-1] / max(c[-2], 1e-12) - 1.
        clv = (2*c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12)
        raw = {
          "miner_2_20270506_vix_regime_reversal_1d": -ret1[s] * (1 + max(stress, 0)),
          "miner_2_20270617_breadth_conditioned_reversal_1d": -ret1[s] * (1 + .5*max(breadth-.5, 0)),
          "miner_1_20270520_overnight_gap_reversal_1d": -gap,
          "miner_1_stress_conditioned_volscaled_reversal_5d": -(ret5[s]-med5) / vol[s] * (1 + max(stress, 0)),
          "reversal_5d_crossasset_20280601": -(ret5[s]-med5),
          "miner_1_20280309_beta_neutral_reversal_5d": -(ret5[s]-med5),
        }
        for fid in ids: scores[fid][s] = direction[fid] * raw.get(fid, 0.)
    composite = {s: .5 for s in ASSETS}
    for fid in ids:
        r = ranks(scores[fid])
        for s in ASSETS: composite[s] += fw[fid] * (r[s] - .5)
    raww = {s: max(.02, composite[s]) / (.85 + .15*vol[s]/medvol) for s in ASSETS}
    if stress > .25 or breadth >= .6 or ret1["SPX"] < 0:
        for s in ("XAU", "US10Y", "CN10Y"): raww[s] *= 1.5
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): raww[s] *= .6
    target = bounded(raww)
    mu = float(np.mean(list(composite.values())))
    sd = max(float(np.std(list(composite.values()))), 1e-9)
    forecast = {s: float(.01 * (composite[s] - mu) / sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_date = dt

