import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(score):
    lo, hi = 0.015, 0.16
    w = {s: lo for s in ASSETS}
    rem = 1.0 - lo * len(ASSETS)
    positive = {s: max(float(score[s]), 1e-6) for s in ASSETS}
    total = sum(positive.values())
    for s in sorted(ASSETS, key=lambda x: score[x], reverse=True):
        add = min(hi - lo, rem * positive[s] / total)
        w[s] += add
        rem -= add
    for s in sorted(ASSETS, key=lambda x: score[x], reverse=True):
        add = min(hi - w[s], max(rem, 0.0))
        w[s] += add
        rem -= add
        if rem <= 1e-12:
            break
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


def vix_stress():
    d = get_index_daily_data(symbol="VIX", days=90)
    if d is None or len(d) < 22:
        return 0.0
    c = np.asarray(d.sort_values("date")["close"], float)
    return float(np.clip(c[-1] / max(np.median(c[-22:-1]), 1e-9) - 1.0, -0.5, 1.5))


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-6:
        return
    ids = [str(f["factor_id"]) for f in selected]
    factors = {str(f["factor_id"]): (float(f["weight"]), int(f.get("direction", 1))) for f in selected}
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS):
        return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 65:
            return
        d = d.sort_values("date")
        data[s] = {k: np.asarray(d[k], float) for k in ("open", "close")}
        data[s]["date"] = str(d.iloc[-1]["date"])
    dt = max(data[s]["date"] for s in ASSETS)
    if last_date is not None:
        try:
            if dt == last_date or np.busday_count(np.datetime64(last_date), np.datetime64(dt)) < 10:
                return
        except Exception:
            return

    stress = vix_stress()
    ret1, ret5, ret10, vol, drawdown = {}, {}, {}, {}, {}
    for s in ASSETS:
        c = data[s]["close"]
        ret1[s] = c[-1] / max(c[-2], 1e-12) - 1.0
        ret5[s] = c[-1] / max(c[-6], 1e-12) - 1.0
        ret10[s] = c[-1] / max(c[-11], 1e-12) - 1.0
        r = np.diff(c[-21:]) / np.maximum(c[-21:-1], 1e-12)
        vol[s] = max(float(np.std(r)), 0.008)
        drawdown[s] = max(0.0, 1.0 - float(c[-1]) / max(float(np.max(c[-61:])), 1e-12))
    breadth = sum(v < 0 for v in ret5.values()) / len(ASSETS)
    medvol = max(float(np.median(list(vol.values()))), 1e-9)
    cross_disp = max(float(np.std(list(ret5.values()))), 1e-9)
    med5 = float(np.median(list(ret5.values())))
    market10 = float(np.mean(list(ret10.values())))
    signals = {fid: {} for fid in ids}
    for s in ASSETS:
        c, o = data[s]["close"], data[s]["open"]
        gap = o[-1] / max(c[-2], 1e-12) - 1.0
        # All inputs are lagged completed-day observations; each named factor has
        # a deterministic, economically aligned proxy in this compact benchmark.
        available = {
            "miner_2_20281005_trend_persistence_10d": ret10[s] / vol[s],
            "miner_2_20280810_volnorm_momentum_5d": ret5[s] / vol[s],
            "miner_3_20280824_dispersion_conditioned_reversal_5d": -(ret5[s] - med5) / max(vol[s], cross_disp),
            "miner_2_20270617_breadth_conditioned_reversal_1d": -ret1[s] * (1.0 + .5 * max(breadth - .5, 0.0)),
            "miner_2_20270506_vix_regime_reversal_1d": -ret1[s] * (1.0 + max(stress, 0.0)),
            "miner_3_20280907_drawdown_weighted_reversal_5d": (-ret5[s] / vol[s]) * (1.0 + min(drawdown[s], .5)),
            "miner_3_20280727_smoothed_reversal_5d": -(0.6 * ret5[s] + 0.4 * ret10[s]),
            "miner_1_20281019_relative_strength_reversal_10d": -((ret10[s] - market10) / vol[s]),
            "miner_3_20281019_leadership_regime_10d": (ret10[s] / vol[s]) * (1.0 if breadth < .6 else .6),
        }
        for fid in ids:
            signals[fid][s] = factors[fid][1] * available.get(fid, 0.0)
    composite = {s: 0.0 for s in ASSETS}
    for fid in ids:
        rr = rank(signals[fid])
        for s in ASSETS:
            composite[s] += factors[fid][0] * rr[s]
    scaled = {s: max(.01, composite[s]) / (1.0 + .20 * vol[s] / medvol) for s in ASSETS}
    if stress > .25 or breadth >= .60 or ret1["SPX"] < 0:
        for s in ("XAU", "US10Y", "CN10Y"):
            scaled[s] *= 1.45
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            scaled[s] *= .65
    target = bounded_weights(scaled)
    mean = float(np.mean(list(composite.values())))
    std = max(float(np.std(list(composite.values()))), 1e-9)
    forecast = {s: float(.01 * (composite[s] - mean) / std) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_date = dt

