import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def ranks(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    n = max(len(good), 1)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.) / n
    return out


def bounded(score):
    lo, hi = .015, .16
    w = {s: lo for s in ASSETS}
    rem = 1. - lo * len(ASSETS)
    total = sum(max(score[s], 1e-9) for s in ASSETS)
    for s in sorted(ASSETS, key=lambda z: score[z], reverse=True):
        add = min(hi - lo, rem * max(score[s], 1e-9) / total)
        w[s] += add
        rem -= add
    for s in sorted(ASSETS, key=lambda z: score[z], reverse=True):
        if rem <= 1e-12: break
        add = min(hi - w[s], rem)
        w[s] += add
        rem -= add
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


def stress_value():
    d = get_index_daily_data(symbol="VIX", days=90)
    if d is None or len(d) < 22: return 0.
    c = np.asarray(d.sort_values("date")["close"], float)
    return float(np.clip(c[-1] / max(np.median(c[-22:-1]), 1e-9) - 1., -.5, 1.5))


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.) > 1e-6:
        return
    ids = [str(f["factor_id"]) for f in selected]
    spec = {str(f["factor_id"]): (float(f["weight"]), int(f.get("direction", 1))) for f in selected}
    if set(get_account_dict().get("watch_list", [])) != set(ASSETS): return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 65: return
        d = d.sort_values("date")
        data[s] = np.asarray(d["close"], float)
        data[s + "_date"] = str(d.iloc[-1]["date"])
    dt = max(data[s + "_date"] for s in ASSETS)
    if last_date is not None:
        try:
            if dt == last_date or np.busday_count(np.datetime64(last_date), np.datetime64(dt)) < 10: return
        except Exception: return

    r1, r5, r10, r20, vol, draw = {}, {}, {}, {}, {}, {}
    for s in ASSETS:
        c = data[s]
        daily = np.diff(c) / np.maximum(c[:-1], 1e-12)
        r1[s] = c[-1] / c[-2] - 1.
        r5[s] = c[-1] / c[-6] - 1.
        r10[s] = c[-1] / c[-11] - 1.
        r20[s] = c[-1] / c[-21] - 1.
        vol[s] = max(float(np.std(daily[-20:])), .008)
        draw[s] = max(0., 1. - c[-1] / max(np.max(c[-61:]), 1e-12))
    med5, med10 = np.median(list(r5.values())), np.median(list(r10.values()))
    dispersion = max(float(np.std(list(r5.values()))), 1e-9)
    medvol = max(float(np.median(list(vol.values()))), 1e-9)
    stress = stress_value()
    breadth = sum(v < 0 for v in r5.values()) / len(ASSETS)
    signals = {fid: {} for fid in ids}
    for s in ASSETS:
        # Each implementation is lagged: the final completed bar is the input.
        raw = {
            "miner_2_20281005_trend_persistence_10d": r10[s] / vol[s],
            "miner_3_20281019_leadership_regime_10d": (r10[s] - med10) / vol[s],
            "miner_2_20260716_risk_adjusted_momentum_20d": r20[s] / vol[s],
            "miner_3_20281130_compression_reversal_5d": -(r5[s] - med5) / max(vol[s], dispersion),
            "miner_3_20280727_smoothed_reversal_5d": -(0.6 * r5[s] + 0.4 * r10[s]) / vol[s],
            "miner_3_20280824_dispersion_conditioned_reversal_5d": -(r5[s] - med5) / max(vol[s], dispersion) * min(dispersion / medvol, 2.),
        }
        for fid in ids:
            signals[fid][s] = spec[fid][1] * raw.get(fid, 0.)
    composite = {s: 0. for s in ASSETS}
    for fid in ids:
        rr = ranks(signals[fid])
        for s in ASSETS: composite[s] += spec[fid][0] * rr[s]
    score = {s: max(composite[s], .01) / (1. + .20 * vol[s] / medvol) for s in ASSETS}
    if stress > .25 or breadth >= .60 or r1["SPX"] < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.45
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): score[s] *= .65
    target = bounded(score)
    mean = np.mean(list(composite.values())); sd = max(np.std(list(composite.values())), 1e-9)
    forecast = {s: float(.01 * (composite[s] - mean) / sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_date = dt

