    result = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        result[s] = (i + 1.0) / max(len(good), 1)
    return result


def bounded(score):
    lo, hi = 0.015, 0.16
    weights = {s: lo for s in ASSETS}
    remaining = 1.0 - lo * len(ASSETS)
    total = sum(max(float(score[s]), 1e-9) for s in ASSETS)
    for s in sorted(ASSETS, key=score.get, reverse=True):
        add = min(hi - lo, remaining * max(score[s], 1e-9) / total)
        weights[s] += add
        remaining -= add
    for s in sorted(ASSETS, key=score.get, reverse=True):
        if remaining <= 1e-12:
            break
        add = min(hi - weights[s], remaining)
        weights[s] += add
        remaining -= add
    total_weight = sum(weights.values())
    return {s: weights[s] / total_weight for s in ASSETS}


def stress():
    d = get_index_daily_data(symbol="VIX", days=90)
    if d is None or len(d) < 22:
        return 0.0
    close = np.asarray(d.sort_values("date")["close"], float)
    return float(np.clip(close[-1] / max(np.median(close[-22:-1]), 1e-9) - 1, -0.5, 1.5))


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-6:
        return
    factor_ids = [str(x["factor_id"]) for x in selected]
    spec = {str(x["factor_id"]): (float(x["weight"]), int(x.get("direction", 1))) for x in selected}
