    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / max(n, 1)
    return out


def allocate(scores):
    # Full investment, diversified bounds; fractional quantities are handled by helper.
    lo, hi = 0.015, 0.16
    out = {s: lo for s in ASSETS}
    remaining = 1.0 - lo * len(ASSETS)
    positive = {s: max(float(scores[s]), 1e-9) for s in ASSETS}
    denom = sum(positive.values())
    for s in sorted(ASSETS, key=lambda x: scores[x], reverse=True):
