        out[s] += add
        remaining -= add
    if remaining > 1e-10:
        for s in sorted(ASSETS, key=lambda x: scores[x], reverse=True):
            add = min(hi - out[s], remaining)
            out[s] += add
            remaining -= add
            if remaining <= 1e-10:
                break
