import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def ranks(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(1, len(good))
    return out


def weights(score):
    lo, hi = 0.015, 0.16
    out = {s: lo for s in ASSETS}
    left = 1.0 - lo * len(ASSETS)
    p = {s: max(float(score[s]), 1e-9) for s in ASSETS}
    for s in sorted(ASSETS, key=score.get, reverse=True):
        add = min(hi - lo, left * p[s] / sum(p.values()))
        out[s] += add
        left -= add
    for s in sorted(ASSETS, key=score.get, reverse=True):
        add = min(hi - out[s], max(0.0, left))
        out[s] += add
        left -= add
    z = sum(out.values())
    return {s: float(out[s] / z) for s in ASSETS}


def stress():
    d = get_index_daily_data(symbol="VIX", days=90)
    if d is None or len(d) < 22:
        return 0.0
    c = np.asarray(d.sort_values("date")["close"], dtype=float)
    return float(c[-1] / max(np.median(c[-22:-1]), 1e-9) - 1.0)


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS):
        return
    factor_ids = [str(f["factor_id"]) for f in selected]
    spec = {str(f["factor_id"]): (float(f["weight"]), int(f.get("direction", 1))) for f in selected}
    px, volu = {}, {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 65:
            return
        d = d.sort_values("date")
        px[s] = np.asarray(d["close"], dtype=float)
        volu[s] = np.asarray(d["volume"], dtype=float) if "volume" in d else np.full(len(d), np.nan)
    decision_date = max(str(px[s][-1]) for s in ASSETS)  # only completed daily bars
    if last_date is not None:
        try:
            if decision_date == last_date or np.busday_count(np.datetime64(last_date), np.datetime64(decision_date)) < 10:
                return
        except Exception:
            return
    r5, r10, r20, r60, rv, dd, vs = {}, {}, {}, {}, {}, {}, {}
    for s, c in px.items():
        rets = np.diff(c) / np.maximum(c[:-1], 1e-12)
        r5[s], r10[s] = c[-1] / c[-6] - 1, c[-1] / c[-11] - 1
        r20[s], r60[s] = c[-1] / c[-21] - 1, c[-1] / c[-61] - 1
        rv[s] = max(float(np.std(rets[-20:])), 0.008)
        dd[s] = c[-1] / max(np.max(c[-61:]), 1e-12) - 1
        v = volu[s]
        vs[s] = float(v[-1] / max(np.nanmean(v[-21:-1]), 1e-12) - 1) if np.isfinite(v).sum() >= 22 else 0.0
    med5, medv = np.median(list(r5.values())), max(np.median(list(rv.values())), 1e-9)
    disp = max(float(np.std(list(r5.values()))), 0.002)
    raw = {fid: {} for fid in factor_ids}
    for s in ASSETS:
        vals = {
            "miner_2_20281005_trend_persistence_10d": r10[s] / rv[s],
            "miner_3_20281019_leadership_regime_10d": (0.55*r10[s] + 0.45*r20[s]) / rv[s],
            "miner_1_20290322_lowvolatility_20d_10d": rv[s] / medv,
            "miner_1_20290322_risk_adjusted_momentum_60_20_10d": (r60[s] - 0.5*r20[s]) / rv[s],
            "miner_1_20290517_volume_confirmed_reversal_10d": (-(r10[s]-med5)/disp) * (1+0.35*np.clip(vs[s], -1, 2)),
            "miner_2_20290322_range_extreme_reversal_5d": -(r5[s]-med5)/disp,
            "miner_3_20280824_dispersion_conditioned_reversal_5d": -(r5[s]-med5)/disp,
            "miner_3_20280907_drawdown_weighted_reversal_5d": -(r5[s]-med5)*(1+max(0, -dd[s]))/rv[s],
        }
        for fid in factor_ids:
            raw[fid][s] = spec[fid][1] * vals.get(fid, 0.0)
    composite = {s: 0.0 for s in ASSETS}
    for fid in factor_ids:
        rr = ranks(raw[fid])
        for s in ASSETS:
            composite[s] += spec[fid][0] * rr[s]
    score = {s: max(composite[s], 0.01) / (1 + 0.20*rv[s]/medv) for s in ASSETS}
    breadth = sum(r5[s] < 0 for s in ASSETS) / len(ASSETS)
    if stress() > 0.25 or breadth >= 0.60 or r10["SPX"] < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.55
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): score[s] *= 0.60
    target = weights(score)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(0.01*(score[s]-mu)/sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_date = decision_date

