import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def pct_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    n = len(good)
    if n:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1) / n
    return out


def bounded_weights(score):
    lo, hi = 0.015, 0.16
    w = {s: lo for s in ASSETS}
    rem = 1.0 - lo * len(ASSETS)
    p = {s: max(float(score[s]), 1e-8) for s in ASSETS}
    for s in sorted(ASSETS, key=lambda x: p[x], reverse=True):
        add = min(hi - lo, rem * p[s] / sum(p.values()))
        w[s] += add
        rem -= add
    for s in sorted(ASSETS, key=lambda x: p[x], reverse=True):
        if rem <= 1e-12: break
        add = min(hi - w[s], rem)
        w[s] += add
        rem -= add
    return {s: w[s] / sum(w.values()) for s in ASSETS}


def vix_stressed():
    d = get_index_daily_data(symbol="VIX", days=130)
    if d is None or len(d) < 65: return False
    c = np.asarray(d.sort_values("date")["close"], dtype=float)
    # lagged VIX only: the final observation is the last completed session.
    return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS): return

    factor_ids = [str(x["factor_id"]) for x in selected]
    spec = {str(x["factor_id"]): (float(x["weight"]), int(x.get("direction", 1))) for x in selected}
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=190)
        if d is None or len(d) < 125: return
        data[s] = d.sort_values("date").reset_index(drop=True)
    date = str(data[ASSETS[0]].iloc[-1]["date"])
    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10: return
        except Exception: return

    ret = {}; vol = {}; volume_ratio = {}
    for s, d in data.items():
        c = np.asarray(d["close"], dtype=float)
        r = np.diff(c) / np.maximum(c[:-1], 1e-12)
        ret[s] = {"r5": c[-1]/c[-6]-1, "r10": c[-1]/c[-11]-1,
                  "r20": c[-1]/c[-21]-1, "r60": c[-1]/c[-61]-1}
        vol[s] = max(float(np.std(r[-20:])), .008)
        v = np.asarray(d["volume"], dtype=float)
        prior = v[-61:-1]
        med = np.nanmedian(prior) if np.isfinite(prior).any() else 0.
        volume_ratio[s] = float(v[-1] / max(med, 1e-12)) if np.isfinite(v[-1]) and med > 0 else 1.

    med5 = np.median([ret[s]["r5"] for s in ASSETS])
    medvol = max(np.median(list(vol.values())), 1e-9)
    dispersion = max(np.std([ret[s]["r5"] for s in ASSETS]), .002)
    # Equal-weight benchmark beta and 5-day residual, matching the admitted factor.
    bench = np.mean([ret[s]["r5"] for s in ASSETS])
    raw = {s: {} for s in ASSETS}
    for s, d in data.items():
        c = np.asarray(d["close"], dtype=float)
        rr = np.diff(c) / np.maximum(c[:-1], 1e-12)
        b = np.asarray([np.mean([np.diff(np.asarray(data[q]["close"], dtype=float)) /
                                  np.maximum(np.asarray(data[q]["close"], dtype=float)[:-1], 1e-12)][i]
                         for q in ASSETS]) for i in range(len(rr))])
        cov = np.cov(rr[-60:], b[-60:], ddof=1)[0,1] if len(rr) >= 60 else 0.
        beta = cov / max(np.var(b[-60:]), 1e-10)
        resid5 = ret[s]["r5"] - beta * bench
        raw[s]["miner_2_20281005_trend_persistence_10d"] = ret[s]["r10"] / vol[s]
        raw[s]["miner_1_20290322_lowvolatility_20d_10d"] = vol[s]
        raw[s]["miner_2_20290920_stress_residual_reversal_10d"] = (-resid5 / vol[s]) if vix_stressed() else 0.
        raw[s]["miner_1_20290322_risk_adjusted_momentum_60_20_10d"] = (ret[s]["r60"] - .5*ret[s]["r20"]) / vol[s]
        raw[s]["miner_1_20290517_volume_confirmed_reversal_10d"] = -(ret[s]["r10"]-med5) * np.clip(volume_ratio[s], .5, 3.)

    score = {s: 0. for s in ASSETS}
    for f in selected:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]: return
        directed = {s: spec[fid][1] * raw[s][fid] for s in ASSETS}
        ranks = pct_rank(directed)
        for s in ASSETS: score[s] += spec[fid][0] * ranks[s]
    # Explicit high-risk defensive overlay, while remaining fully invested.
    if vix_stressed() or sum(ret[s]["r5"] < 0 for s in ASSETS) >= 9 or ret["SPX"]["r10"] < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.45
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): score[s] *= .65
    score = {s: max(score[s], .01) / (1 + .20 * vol[s] / medvol) for s in ASSETS}
    target = bounded_weights(score)
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01 * (score[s]-avg) / sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_date = date

