import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / len(good)
    return out


def bounded(score):
    lo, hi = .015, .16
    w = {s: lo for s in ASSETS}
    rem = 1.0 - lo * len(ASSETS)
    total = sum(max(score[s], 1e-8) for s in ASSETS)
    for s in sorted(ASSETS, key=score.get, reverse=True):
        add = min(hi - lo, rem * max(score[s], 1e-8) / total)
        w[s] += add
        rem -= add
    for s in sorted(ASSETS, key=score.get, reverse=True):
        if rem <= 1e-12:
            break
        add = min(hi - w[s], rem)
        w[s] += add
        rem -= add
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


def stressed_market():
    d = get_index_daily_data(symbol="VIX", days=130)
    if d is None or len(d) < 65:
        return False
    c = np.asarray(d.sort_values("date")["close"], dtype=float)
    return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS):
        return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=190)
        if d is None or len(d) < 125:
            return
        data[s] = d.sort_values("date").reset_index(drop=True)
    date = str(data[ASSETS[0]].iloc[-1]["date"])
    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10:
                return
        except Exception:
            return

    ret, vol, volume_ratio = {}, {}, {}
    for s, d in data.items():
        c = np.asarray(d["close"], dtype=float)
        r = np.diff(c) / np.maximum(c[:-1], 1e-12)
        ret[s] = {"r5": c[-1] / c[-6] - 1, "r10": c[-1] / c[-11] - 1,
                  "r20": c[-1] / c[-21] - 1, "r60": c[-1] / c[-61] - 1}
        vol[s] = max(float(np.std(r[-20:])), .008)
        v = np.asarray(d["volume"], dtype=float)
        med = np.nanmedian(v[-61:-1])
        volume_ratio[s] = float(v[-1] / med) if np.isfinite(v[-1]) and med > 0 else 1.0

    # Cross-asset benchmark series for residual and relative-strength signals.
    series = {s: np.asarray(data[s]["close"], dtype=float) for s in ASSETS}
    returns = {s: np.diff(series[s]) / np.maximum(series[s][:-1], 1e-12) for s in ASSETS}
    bench = np.mean(np.array([returns[s][-60:] for s in ASSETS]), axis=0)
    bench_10 = float(np.mean([ret[s]["r10"] for s in ASSETS]))
    med5 = float(np.median([ret[s]["r5"] for s in ASSETS]))
    raw = {s: {} for s in ASSETS}
    for s in ASSETS:
        beta = np.cov(returns[s][-60:], bench, ddof=1)[0, 1] / max(np.var(bench), 1e-10)
        residual = ret[s]["r5"] - beta * bench_10
        # Names intentionally mirror the persisted screener IDs.
        raw[s]["miner_2_20281005_trend_persistence_10d"] = ret[s]["r10"] / vol[s]
        raw[s]["miner_1_20290322_lowvolatility_20d_10d"] = vol[s]
        raw[s]["miner_2_20290920_stress_residual_reversal_10d"] = -residual / vol[s]
        # Recovery from a short-term range extreme, with a modest volatility scale.
        short = ret[s]["r5"]
        raw[s]["miner_2_20290322_range_extreme_reversal_5d"] = -short / vol[s]
        raw[s]["miner_1_20290517_volume_confirmed_reversal_10d"] = -(ret[s]["r10"] - med5) * np.clip(volume_ratio[s], .5, 3.0)
        raw[s]["miner_1_20281019_relative_strength_reversal_10d"] = -(ret[s]["r20"] - np.median([ret[q]["r20"] for q in ASSETS])) / vol[s]

    spec = {str(x["factor_id"]): (float(x["weight"]), int(x.get("direction", 1))) for x in selected}
    score = {s: 0.0 for s in ASSETS}
    for f in selected:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]:
            return
        rr = ranks({s: spec[fid][1] * raw[s][fid] for s in ASSETS})
        for s in ASSETS:
            score[s] += spec[fid][0] * rr[s]

    risk = stressed_market() or sum(ret[s]["r5"] < 0 for s in ASSETS) >= 9 or ret["SPX"]["r10"] < 0
    if risk:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.45
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            score[s] *= .65
    median_vol = max(float(np.median(list(vol.values()))), 1e-9)
    score = {s: max(score[s], .01) / (1 + .20 * vol[s] / median_vol) for s in ASSETS}
    target = bounded(score)
    avg, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - avg) / sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(x["factor_id"]) for x in selected],
                         horizon_days=10)
    last_date = date

