import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None

def rank_cs(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    n = len(good)
    for i, (s, _) in enumerate(good): out[s] = (i + 1) / n
    return out

def weights(score):
    # Full investment, diversified and bounded for the 15-asset cross-section.
    lo, hi = .015, .16
    w = {s: lo for s in ASSETS}; left = 1 - lo * len(ASSETS)
    p = {s: max(score[s], 1e-8) for s in ASSETS}; z = sum(p.values())
    for s in sorted(ASSETS, key=score.get, reverse=True):
        a = min(hi-lo, left*p[s]/z); w[s] += a; left -= a
    for s in sorted(ASSETS, key=score.get, reverse=True):
        a = min(hi-w[s], max(left, 0)); w[s] += a; left -= a
        if left < 1e-12: break
    z = sum(w.values()); return {s: w[s]/z for s in ASSETS}

def stressed():
    try:
        d = get_index_daily_data(symbol="VIX", days=130)
        if d is None or len(d) < 65: return False
        c = np.asarray(d.sort_values("date")["close"], float)
        return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])
    except Exception: return False

@register_hook
def strategy():
    global last_date
    try: selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception: return
    if not selected or abs(sum(float(x["weight"]) for x in selected)-1) > 1e-6: return
