    raw = {s:{} for s in ASSETS}
    for s in ASSETS:
        rr = ret[s][-80:]; beta=np.cov(rr, bench, ddof=1)[0,1]/max(np.var(bench),1e-10)
        resid = rr-beta*bench; resid5=float(np.sum(resid[-5:])); residvol=max(float(np.std(resid[-20:])),.008)
