          "miner_2_20290920_stress_residual_reversal_10d": -resid5/residvol if stressed() else 0.,
          "miner_1_20290322_risk_adjusted_momentum_60_20_10d": r[s]["r60"]/recent_std,
          "miner_1_20290517_volume_confirmed_reversal_10d": -r[s]["r10"]*volume_ratio[s],
          "miner_1_20260716_peer_median_leadlag_5d": float(np.median([r[x]["r5"] for x in ASSETS if x != s])),
          "miner_3_20300207_recovery_boost_10d": (-recovery/recent_std)*(1+10*max(r[s]["r60"],0)),
          "miner_3_20281130_compression_reversal_5d": -r[s]["r10"]/recent_std*np.clip(long_std/recent_std,.5,2),
          "miner_1_20281019_relative_strength_reversal_10d": -resid5/residvol,
        }
