        q=rank_cs({s:direction*raw[s][fid] for s in ASSETS})
        for s in ASSETS: score[s]+=wt*q[s]
    defensive=stressed() or sum(r[s]["r5"]<0 for s in ASSETS)>=9 or r["SPX"]["r10"]<0
    if defensive:
        for s in ("XAU","US10Y","CN10Y"): score[s]*=1.45
        for s in ("BTC","ETH","WTI","SOX","NDX"): score[s]*=.65
    med=np.median(list(vol.values())); score={s:max(score[s],.01)/(1+.20*vol[s]/max(med,1e-9)) for s in ASSETS}
    target=weights(score); mu=np.mean(list(score.values())); sd=max(np.std(list(score.values())),1e-9)
    forecast={s:float(.01*(score[s]-mu)/sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=list(spec), horizon_days=10)
    last_date=date

