import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def cs_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(scores):
    lo, hi = 0.015, 0.16
    w = {s: lo for s in ASSETS}
    remaining = 1.0 - lo * len(ASSETS)
    positive = {s: max(float(scores[s]), 1e-8) for s in ASSETS}
    total = sum(positive.values())
    for s in ASSETS:
        add = min(hi - lo, remaining * positive[s] / total)
        w[s] += add
        remaining -= add
    for s in sorted(ASSETS, key=lambda x: scores[x], reverse=True):
        if remaining <= 1e-12:
            break
        add = min(hi - w[s], remaining)
        w[s] += add
        remaining -= add
    total = sum(w.values())
    return {s: w[s] / total for s in ASSETS}


def vix_stress():
    try:
        d = get_index_daily_data(symbol="VIX", days=130)
        if d is None or len(d) < 65:
            return False
        c = np.asarray(d.sort_values("date")["close"], float)
        return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])
    except Exception:
        return False


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS):
        return

    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=200)
        if d is None or len(d) < 125:
            return
        data[s] = d.sort_values("date").reset_index(drop=True)
    date = str(data[ASSETS[0]].iloc[-1]["date"])
    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10:
                return
        except Exception:
            return

    close = {s: np.asarray(data[s]["close"], float) for s in ASSETS}
    ret = {s: np.diff(close[s]) / np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    r = {s: {"r5": close[s][-1] / close[s][-6] - 1,
             "r10": close[s][-1] / close[s][-11] - 1,
             "r20": close[s][-1] / close[s][-21] - 1,
             "r60": close[s][-1] / close[s][-61] - 1} for s in ASSETS}
    vol = {s: max(float(np.std(ret[s][-20:])), 0.008) for s in ASSETS}
    vr = {}
    for s in ASSETS:
        v = np.asarray(data[s]["volume"], float)
        med = np.nanmedian(v[-61:-1])
        vr[s] = float(np.clip(v[-1] / med, .5, 3.0)) if med > 0 and np.isfinite(v[-1]) else 1.0

    bench = np.mean(np.array([ret[s][-80:] for s in ASSETS]), axis=0)
    raw = {s: {} for s in ASSETS}
    for s in ASSETS:
        rr = ret[s][-80:]
        beta = np.cov(rr, bench, ddof=1)[0, 1] / max(np.var(bench), 1e-10)
        resid = rr - beta * bench
        resid5 = float(np.sum(resid[-5:]))
        residvol = max(float(np.std(resid[-20:])), .008)
        persistence = float(np.mean(np.sign(ret[s][-20:])) - .5)
        recent = max(float(np.std(ret[s][-20:])), .008)
        long = max(float(np.std(ret[s][-60:])), .008)
        recovery = max(close[s][-1] / np.max(close[s][-121:-1]) - 1, -1)
        raw[s] = {
            "miner_2_20281005_trend_persistence_10d": persistence * r[s]["r20"] / recent,
            "miner_2_20290920_stress_residual_reversal_10d": -resid5 / residvol if vix_stress() else 0.0,
            "miner_1_20290322_risk_adjusted_momentum_60_20_10d": r[s]["r60"] / recent,
            "miner_1_20290517_volume_confirmed_reversal_10d": -r[s]["r10"] * vr[s],
            "miner_1_20281019_relative_strength_reversal_10d": -resid5 / residvol,
            "miner_1_20260716_peer_median_leadlag_5d": float(np.median([r[x]["r5"] for x in ASSETS if x != s])),
            "miner_3_20281130_compression_reversal_5d": -r[s]["r10"] / recent * np.clip(long / recent, .5, 2),
            "miner_3_20300307_recovery_boost4_10d": (-recovery / recent) * (1 + 10 * max(r[s]["r60"], 0)),
        }

    spec = {str(x["factor_id"]): (float(x["weight"]), int(x.get("direction", 1))) for x in selected}
    if any(fid not in raw[ASSETS[0]] for fid in spec):
        return
    score = {s: 0.0 for s in ASSETS}
    for fid, (weight, direction) in spec.items():
        ranks = cs_rank({s: direction * raw[s][fid] for s in ASSETS})
        for s in ASSETS:
            score[s] += weight * ranks[s]

    stressed = vix_stress() or sum(r[s]["r5"] < 0 for s in ASSETS) >= 9 or r["SPX"]["r10"] < 0
    if stressed:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.45
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            score[s] *= .65
    median_vol = max(float(np.median(list(vol.values()))), 1e-9)
    score = {s: max(score[s], .01) / (1 + .20 * vol[s] / median_vol) for s in ASSETS}
    target = bounded_weights(score)
    mean_score = float(np.mean(list(score.values())))
    std_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - mean_score) / std_score) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=list(spec.keys()), horizon_days=10)
    last_date = date

