import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def cross_rank(values):
    ordered = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(ordered):
        out[s] = (i + 1) / max(len(ordered), 1)
    return out


def bounded_weights(score):
    # Full investment, diversified 15-asset portfolio; no cash sleeve.
    lo, hi = 0.015, 0.16
    w = {s: lo for s in ASSETS}
    rem = 1.0 - lo * len(ASSETS)
    positive = {s: max(float(score[s]), 1e-8) for s in ASSETS}
    total = sum(positive.values())
    for s in ASSETS:
        add = min(hi - lo, rem * positive[s] / total)
        w[s] += add
        rem -= add
    for s in sorted(ASSETS, key=lambda x: score[x], reverse=True):
        add = min(hi - w[s], rem)
        w[s] += add
        rem -= add
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


def stressed_market():
    try:
        d = get_index_daily_data(symbol="VIX", days=130)
        if d is None or len(d) < 65:
            return False
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])
    except Exception:
        return False


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS):
        return

    data = {}
    for symbol in ASSETS:
        d = get_stock_daily_data(symbol=symbol, days=200)
        if d is None or len(d) < 125:
            return
        data[symbol] = d.sort_values("date").reset_index(drop=True)
    date = str(data[ASSETS[0]].iloc[-1]["date"])
    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10:
                return
        except Exception:
            return

    close = {s: np.asarray(data[s]["close"], dtype=float) for s in ASSETS}
    daily = {s: np.diff(close[s]) / np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    ret = {s: {n: close[s][-1] / close[s][-n-1] - 1.0 for n in (5, 10, 20, 60)} for s in ASSETS}
    vol = {s: max(float(np.std(daily[s][-20:])), 0.008) for s in ASSETS}
    benchmark = np.mean(np.array([daily[s][-80:] for s in ASSETS]), axis=0)
    dispersion = float(np.mean([np.std(daily[s][-20:]) for s in ASSETS]))
    raw = {s: {} for s in ASSETS}

    for s in ASSETS:
        rr = daily[s][-80:]
        beta = np.cov(rr, benchmark, ddof=1)[0, 1] / max(np.var(benchmark), 1e-10)
        residual = rr - beta * benchmark
        residual_vol = max(float(np.std(residual[-20:])), 0.008)
        volume = np.asarray(data[s]["volume"], dtype=float)
        median_volume = np.nanmedian(volume[-61:-1])
        volume_ratio = float(np.clip(volume[-1] / median_volume, 0.5, 3.0)) if median_volume > 0 else 1.0
        persistence = (np.mean(np.sign(daily[s][-20:])) - 0.5) * ret[s][20] / vol[s]
        recovery = close[s][-1] / max(close[s][-121:-1]) - 1.0
        raw[s] = {
            "miner_2_20281005_trend_persistence_10d": persistence,
            "miner_1_20290322_risk_adjusted_momentum_60_20_10d": ret[s][60] / vol[s],
            "miner_2_20290920_stress_residual_reversal_10d": -float(np.sum(residual[-10:])) / residual_vol,
            "miner_3_20300307_recovery_boost4_10d": (-recovery / vol[s]) * (1.0 + 10.0 * max(ret[s][60], 0.0)),
            "miner_1_20291213_volume_confirmed_intermediate_momentum_10d": ret[s][20] / vol[s] * volume_ratio,
            "miner_1_20290712_downside_adjusted_reversal_10d": -ret[s][10] / vol[s],
        }

    spec = {str(x["factor_id"]): (float(x["weight"]), int(x.get("direction", 1))) for x in selected}
    if any(fid not in raw[ASSETS[0]] for fid in spec):
        return
    score = {s: 0.0 for s in ASSETS}
    for fid, (weight, direction) in spec.items():
        ranks = cross_rank({s: direction * raw[s][fid] for s in ASSETS})
        for s in ASSETS:
            score[s] += weight * ranks[s]

    bearish = stressed_market() or sum(ret[s][10] < 0 for s in ASSETS) >= 9 or ret["SPX"][10] < 0
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.45
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            score[s] *= 0.65
    median_vol = max(float(np.median(list(vol.values()))), 1e-9)
    score = {s: max(score[s], 0.01) / (1.0 + 0.20 * vol[s] / median_vol) for s in ASSETS}
    target = bounded_weights(score)
    mean_score = float(np.mean(list(score.values())))
    std_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean_score) / std_score) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=list(spec), horizon_days=10)
    last_date = date

