def rank_xs(vals):
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / max(1, len(good))
    return out


def make_weights(score):
    # Full investment, diversified, with sensible 15-asset bounds.
    lo, hi = 0.015, 0.16
    w = {s: lo for s in ASSETS}
    rem = 1.0 - lo * len(ASSETS)
    p = {s: max(score[s], 1e-8) for s in ASSETS}
    for s in ASSETS:
        add = min(hi - lo, rem * p[s] / sum(p.values()))
        w[s] += add
        rem -= add
    for s in sorted(ASSETS, key=lambda x: score[x], reverse=True):
        add = min(hi - w[s], rem)
        w[s] += add
        rem -= add
    if rem > 1e-10:
        for s in ASSETS:
            add = min(hi - w[s], rem)
            w[s] += add
            rem -= add
            if rem <= 1e-10: break
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


def high_risk():
    try:
        d = get_index_daily_data(symbol="VIX", days=130)
        if d is None or len(d) < 65: return False
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])
    except Exception:
        return False


