        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10: return
        except Exception: return

    close = {s: np.asarray(data[s]["close"], dtype=float) for s in ASSETS}
    daily = {s: np.diff(close[s]) / np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    ret = {s: {n: close[s][-1] / close[s][-n-1] - 1 for n in (5, 10, 20, 60)} for s in ASSETS}
