            "miner_2_20291213_residual_reversal_blend_5_10d": -(np.sum(resid[-5:]) / rv + np.sum(resid[-10:]) / rv) / 2,
            "miner_1_20290322_risk_adjusted_momentum_60_20_10d": ret[s][60] / vol[s],
