    if any(fid not in raw[ASSETS[0]] for fid in spec): return
    score = {s: 0.0 for s in ASSETS}
    for fid, (wt, direction) in spec.items():
        rr = rank_xs({s: direction * raw[s][fid] for s in ASSETS})
        for s in ASSETS: score[s] += wt * rr[s]
    bearish = high_risk() or sum(ret[s][10] < 0 for s in ASSETS) >= 9 or ret["SPX"][10] < 0
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.35
