    med = max(float(np.median(list(vol.values()))), 1e-9)
    score = {s:max(score[s],.01)/(1+.20*vol[s]/med) for s in ASSETS}
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01*(score[s]-avg)/sd) for s in ASSETS}
    rebalance_to_weights(make_weights(score), forecast_returns=forecast, factor_ids=list(spec), horizon_days=10)
    last_date = date

