ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None


def cross_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / max(len(valid), 1)
    return out


def bounded_weights(scores):
    lo, hi = 0.015, 0.16
    weights = {s: lo for s in ASSETS}
    remaining = 1.0 - lo * len(ASSETS)
    total = sum(max(float(scores[s]), 1e-9) for s in ASSETS)
    for s in ASSETS:
        add = min(hi - lo, remaining * max(float(scores[s]), 1e-9) / total)
        weights[s] += add
        remaining -= add
    for s in sorted(ASSETS, key=lambda x: scores[x], reverse=True):
        add = min(hi - weights[s], remaining)
        weights[s] += add
        remaining -= add
        if remaining <= 1e-10:
            break
    total = sum(weights.values())
    return {s: float(weights[s] / total) for s in ASSETS}


def high_risk():
    vix = get_index_daily_data(symbol="VIX", days=130)
    if vix is None or len(vix) < 65:
        return False
    c = np.asarray(vix.sort_values("date")["close"], dtype=float)
    return bool(c[-1] > np.median(c[-61:]) and c[-1] > c[-6])


@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS):
        return

    data = {}
    for symbol in ASSETS:
        df = get_stock_daily_data(symbol=symbol, days=220)
        if df is None or len(df) < 125:
            return
        data[symbol] = df.sort_values("date").reset_index(drop=True)
    decision_date = str(data[ASSETS[0]].iloc[-1]["date"])
    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(decision_date)) < 10:
                return
        except Exception:
            return

    close = {s: np.asarray(data[s]["close"], dtype=float) for s in ASSETS}
    daily = {s: np.diff(close[s]) / np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    returns = {s: {n: close[s][-1] / close[s][-n-1] - 1.0 for n in (5, 20, 60)} for s in ASSETS}
    vol = {s: max(float(np.std(daily[s][-20:])), 0.008) for s in ASSETS}
    benchmark = np.mean(np.array([daily[s][-80:] for s in ASSETS]), axis=0)
    raw = {s: {} for s in ASSETS}
    for s in ASSETS:
        r = daily[s][-80:]
        beta = np.cov(r, benchmark, ddof=1)[0, 1] / max(np.var(benchmark), 1e-10)
        residual = r - beta * benchmark
        residual_vol = max(float(np.std(residual[-20:])), 0.008)
        peer = float(np.median([returns[t][5] for t in ASSETS if t != s]))
        prior = close[s][:-1]
        recovery = -(prior[-1] / max(np.max(prior[-120:]), 1e-12) - 1.0) / vol[s]
        recovery *= 1.0 + 10.0 * max(prior[-1] / max(prior[-61], 1e-12) - 1.0, 0.0)
        volume = np.asarray(data[s].get("volume", np.ones(len(data[s]))), dtype=float)
        volume_ratio = np.nanmean(volume[-20:]) / max(np.nanmean(volume[-60:]), 1e-12)
        raw[s] = {
            "miner_2_20281005_trend_persistence_10d": (np.mean(np.sign(daily[s][-20:])) - 0.5) * returns[s][20] / vol[s],
