            "miner_1_20290322_risk_adjusted_momentum_60_20_10d": returns[s][60] / vol[s],
            "miner_2_20290920_stress_residual_reversal_10d": -np.sum(residual[-10:]) / residual_vol,
            "peer_median_leadlag_5d": returns[s][5] - peer,
        }

    spec = {str(x["factor_id"]): (float(x["weight"]), int(x.get("direction", 1))) for x in selected}
    if any(fid not in raw[ASSETS[0]] for fid in spec):
        return
    score = {s: 0.0 for s in ASSETS}
    for fid, (weight, direction) in spec.items():
        ranked = cross_rank({s: direction * raw[s][fid] for s in ASSETS})
        for s in ASSETS:
            score[s] += weight * ranked[s]

    bearish = high_risk() or sum(returns[s][5] < 0 for s in ASSETS) >= 9 or returns["SPX"][5] < 0
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.55
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            score[s] *= 0.60
    median_vol = max(float(np.median(list(vol.values()))), 1e-9)
    score = {s: max(score[s], 0.01) / (1.0 + 0.20 * vol[s] / median_vol) for s in ASSETS}
    mean_score = np.mean(list(score.values()))
    std_score = max(np.std(list(score.values())), 1e-9)
    forecast_returns = {s: float(0.01 * (score[s] - mean_score) / std_score) for s in ASSETS}
    targets = bounded_weights(score)
    if set(targets) != set(ASSETS) or any(not np.isfinite(v) or v < 0 for v in targets.values()):
        return
    rebalance_to_weights(targets, forecast_returns=forecast_returns,
                         factor_ids=list(spec.keys()), horizon_days=10)
    last_date = decision_date

