import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_account_dict,
    get_stock_daily_data, get_index_daily_data, rebalance_to_weights)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None

def ranks(x):
    vals = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    n = len(vals)
    for i, (s, _) in enumerate(vals):
        out[s] = (i + 1.) / max(n, 1)
    return out

def weights(score):
    floor, cap = .015, .16
    w = {s: floor + (1 - 15 * floor) * max(score[s], 1e-9) /
         sum(max(score[x], 1e-9) for x in ASSETS) for s in ASSETS}
    # Redistribute cap excess while preserving all 15 assets and full investment.
    for _ in range(20):
        over = [s for s in ASSETS if w[s] > cap + 1e-12]
        if not over: break
        excess = sum(w[s] - cap for s in over)
        for s in over: w[s] = cap
        free = [s for s in ASSETS if s not in over]
        den = sum(max(score[s], 1e-9) for s in free)
        for s in free: w[s] += excess * max(score[s], 1e-9) / max(den, 1e-12)
    den = sum(w.values())
    return {s: float(w[s] / den) for s in ASSETS}

def vix_stress():
    d = get_index_daily_data(symbol="VIX", days=130)
    if d is None or len(d) < 60: return 0.0
    c = np.asarray(d.sort_values("date")["close"], float)
    lo, hi = np.percentile(c[:-1], 50), np.percentile(c[:-1], 90)
    return float(np.clip((c[-1] - lo) / max(hi - lo, 1e-9), 0, 1))

@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS): return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=220)
        if d is None or len(d) < 125: return
        data[s] = d.sort_values("date").reset_index(drop=True)
    date = str(data[ASSETS[0]].iloc[-1]["date"])
    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10: return
        except Exception: return
    close = {s: np.asarray(data[s]["close"], float) for s in ASSETS}
    ret = {s: np.diff(close[s]) / np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    r5 = {s: close[s][-1] / close[s][-6] - 1. for s in ASSETS}
    r10 = {s: close[s][-1] / close[s][-11] - 1. for s in ASSETS}
    vol = {s: max(float(np.std(ret[s][-20:])), .008) for s in ASSETS}
    bench = np.mean([ret[s][-80:] for s in ASSETS], axis=0)
    breadth = np.mean([close[s][-1] > close[s][-21] for s in ASSETS])
    stress = vix_stress()
    raw = {s: {} for s in ASSETS}
    for s in ASSETS:
        rr = ret[s][-80:]
        beta = np.cov(rr, bench, ddof=1)[0, 1] / max(np.var(bench), 1e-10)
        resid = rr - beta * bench
        rv = max(float(np.std(resid[-20:])), .008)
        raw[s]["miner_1_20310710_efficiency_weighted_momentum_10d"] = (r10[s]/vol[s]) * (1-abs(r10[s])/(abs(r10[s])+.02))
        raw[s]["miner_1_20310626_breadth33_conditioned_momentum_10d"] = (r10[s]/vol[s]) * (1 if breadth >= .50 else -.35)
        raw[s]["miner_2_20281005_trend_persistence_10d"] = r10[s]/vol[s]
        raw[s]["miner_2_20290920_stress_residual_reversal_10d"] = -np.sum(resid[-10:])/rv * max(stress, .25)
        raw[s]["miner_2_20290322_range_extreme_reversal_5d"] = -r5[s]/vol[s]
        raw[s]["miner_2_20310529_vix_level_reversal_5d_10d"] = -r5[s]/vol[s] * max(stress, .25)
        raw[s]["miner_3_20280921_beta_neutral_reversal_5d"] = -(r5[s]-beta*np.mean(bench[-5:]))/vol[s]
    score = {s: 0. for s in ASSETS}
    for f in selected:
        fid, direction = str(f["factor_id"]), int(f.get("direction", 1))
        rr = ranks({s: direction * raw[s].get(fid, 0.) for s in ASSETS})
        for s in ASSETS: score[s] += float(f["weight"]) * rr[s]
    if stress >= .15 or breadth < .40:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.8
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): score[s] *= .45
    med = np.median(list(vol.values()))
    score = {s: max(score[s], .01)/(1 + .20*vol[s]/max(med, 1e-12)) for s in ASSETS}
    target = weights(score)
