ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None

def cross_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(len(good), 1)
    return out

def bounded_weights(score):
    floor, cap = 0.015, 0.16
    base = {s: max(float(score[s]), 1e-8) for s in ASSETS}
    w = {s: floor + (1 - 15 * floor) * base[s] / sum(base.values()) for s in ASSETS}
    for _ in range(30):
        over = [s for s in ASSETS if w[s] > cap + 1e-12]
        if not over: break
        excess = sum(w[s] - cap for s in over)
        for s in over: w[s] = cap
        free = [s for s in ASSETS if s not in over]
        den = sum(base[s] for s in free)
        for s in free: w[s] += excess * base[s] / max(den, 1e-12)
    z = sum(w.values())
    return {s: float(w[s] / z) for s in ASSETS}

def stress_level():
    d = get_index_daily_data(symbol="VIX", days=130)
    if d is None or len(d) < 60: return 0.0
    c = np.asarray(d.sort_values("date")["close"], float)
    lo, hi = np.percentile(c[:-1], [50, 90])
    return float(np.clip((c[-1] - lo) / max(hi - lo, 1e-9), 0, 1))

@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS): return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=220)
        if d is None or len(d) < 125: return
