    if last_date is not None:
        try:
            if np.busday_count(np.datetime64(last_date), np.datetime64(date)) < 10: return
        except Exception: return
    close = {s: np.asarray(data[s]["close"], float) for s in ASSETS}
    volume = {s: np.asarray(data[s]["volume"], float) for s in ASSETS}
    ret = {s: np.diff(close[s]) / np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    r5 = {s: close[s][-1] / close[s][-6] - 1.0 for s in ASSETS}
    r10 = {s: close[s][-1] / close[s][-11] - 1.0 for s in ASSETS}
    vol = {s: max(float(np.std(ret[s][-20:])), .008) for s in ASSETS}
    bench = np.mean([ret[s][-80:] for s in ASSETS], axis=0)
    breadth = np.mean([close[s][-1] > close[s][-21] for s in ASSETS])
    stress = stress_level()
    raw = {s: {} for s in ASSETS}
    for s in ASSETS:
        rr = ret[s][-80:]
        beta = np.cov(rr, bench, ddof=1)[0, 1] / max(np.var(bench), 1e-10)
        resid = rr - beta * bench
        rv = max(float(np.std(resid[-20:])), .008)
        vratio = np.mean(volume[s][-5:]) / max(np.mean(volume[s][-30:]), 1e-12)
        raw[s]["miner_1_20310710_efficiency_weighted_momentum_10d"] = (r10[s] / vol[s]) * (1 - abs(r10[s]) / (abs(r10[s]) + .02))
        raw[s]["miner_2_20281005_trend_persistence_10d"] = r10[s] / vol[s]
        raw[s]["miner_2_20290920_stress_residual_reversal_10d"] = -np.sum(resid[-10:]) / rv * max(stress, .25)
        raw[s]["miner_1_20310626_breadth33_conditioned_momentum_10d"] = (r10[s] / vol[s]) * (1 if breadth >= .50 else -.35)
        raw[s]["miner_2_20290322_range_extreme_reversal_5d"] = -r5[s] / vol[s]
        raw[s]["miner_3_20280921_beta_neutral_reversal_5d"] = -(r5[s] - beta * np.mean(bench[-5:])) / vol[s]
        raw[s]["miner_1_20290517_volume_confirmed_reversal_10d"] = (-r10[s] / vol[s]) * np.clip(vratio, .5, 2.0)
    score = {s: 0.0 for s in ASSETS}
    for f in selected:
        fid, direction = str(f["factor_id"]), int(f.get("direction", 1))
        ranked = cross_rank({s: direction * raw[s].get(fid, 0.0) for s in ASSETS})
        for s in ASSETS: score[s] += float(f["weight"]) * ranked[s]
    # High stress/weak breadth is expressed by defensive tradable assets, never cash.
    if stress >= .15 or breadth < .40:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 2.0
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): score[s] *= .35
    med = np.median(list(vol.values()))
    score = {s: max(score[s], .01) / (1 + .20 * vol[s] / max(med, 1e-12)) for s in ASSETS}
    target = bounded_weights(score)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01 * (score[s] - mean) / sd) for s in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in selected], horizon_days=10)
    last_date = date

