    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / max(len(good), 1)
    return out

def make_weights(score):
    floor, cap = 0.015, 0.16
    b = {s: max(float(score[s]), 1e-8) for s in ASSETS}
    w = {s: floor + (1 - 15 * floor) * b[s] / sum(b.values()) for s in ASSETS}
    for _ in range(30):
        over = [s for s in ASSETS if w[s] > cap]
        if not over: break
        excess = sum(w[s] - cap for s in over)
        for s in over: w[s] = cap
        free = [s for s in ASSETS if s not in over]
        den = sum(b[s] for s in free)
        for s in free: w[s] += excess * b[s] / max(den, 1e-12)
