ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None

def cs_rank(values):
    vals = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(vals):
        out[s] = (i + 1) / max(len(vals), 1)
    return out

def weights(score):
    floor, cap = 0.015, 0.16
    b = {s: max(float(score[s]), 1e-8) for s in ASSETS}
    w = {s: floor + (1-floor*len(ASSETS))*b[s]/sum(b.values()) for s in ASSETS}
    for _ in range(30):
        high = [s for s in ASSETS if w[s] > cap + 1e-12]
        if not high: break
        excess = sum(w[s]-cap for s in high)
        for s in high: w[s] = cap
        free = [s for s in ASSETS if s not in high]
        den = sum(b[s] for s in free)
        for s in free: w[s] += excess*b[s]/max(den, 1e-12)
    z = sum(w.values())
    return {s: float(w[s]/z) for s in ASSETS}

def vix_level():
    d = get_index_daily_data(symbol="VIX", days=130)
    if d is None or len(d) < 60: return 0.5
    c = np.asarray(d.sort_values("date")["close"], float)
    ref = np.median(c[:-1])
    return float(np.clip((c[-1]-ref)/max(np.percentile(c[:-1],90)-ref,1e-9), 0, 1))

@register_hook
def strategy():
    global last_date
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if (not selected or abs(sum(float(f["weight"]) for f in selected)-1) > 1e-6
            or set(get_account_dict().get("watch_list", [])) != set(ASSETS)):
        return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=230)
        if d is None or len(d) < 125: return
        data[s] = d.sort_values("date").reset_index(drop=True)
    day = str(data[ASSETS[0]].iloc[-1]["date"])[:10]
    if last_date is not None and np.busday_count(np.datetime64(last_date), np.datetime64(day)) < 10: return
    close = {s: np.asarray(data[s]["close"], float) for s in ASSETS}
    daily = {s: np.diff(close[s])/np.maximum(close[s][:-1],1e-12) for s in ASSETS}
    vol = {s: max(float(np.std(daily[s][-20:])), .008) for s in ASSETS}
    breadth = np.mean([close[s][-1] > close[s][-21] for s in ASSETS])
    stress = vix_level()
    raw = {s:{} for s in ASSETS}
    for s in ASSETS:
        c, r, v = close[s], daily[s], vol[s]
        m10, m20 = c[-1]/c[-11]-1, c[-1]/c[-21]-1
        raw[s]["miner_1_20310710_efficiency_weighted_momentum_10d"] = m10/v
        raw[s]["miner_2_81005_trend_persistence_10d"] = np.mean(r[-10:]>0)-.5+.5*m20/v
        raw[s]["miner_1_20310626_breadth33_conditioned_momentum_10d"] = m10/v*(breadth if breadth>=.33 else .25)
        raw[s]["miner_2_20290920_stress_residual_reversal_10d"] = -m10/v*max(stress,.25)
        raw[s]["miner_2_20270506_vix_regime_reversal_1d"] = -r[-1]/v*(.5+stress)
        raw[s]["miner_1_20281005_smoothed_reversal_10d"] = -np.mean([c[-1]/c[-k-1]-1 for k in (5,10,15)])/v
    score = {s:0.0 for s in ASSETS}
    for f in selected:
        fid, direction = str(f["factor_id"]), int(f.get("direction",1))
        ranked = cs_rank({s: direction*raw[s].get(fid,0.0) for s in ASSETS})
        for s in ASSETS: score[s] += float(f["weight"])*ranked[s]
    # Medium-high, weakening regime: remain fully invested but make defensives the anchor.
    if stress >= .15 or breadth < .40:
        for s in ("XAU","US10Y","CN10Y"): score[s] *= 2.5
        for s in ("BTC","ETH","WTI","SOX","NDX","COPPER"): score[s] *= .35
    medvol = np.median(list(vol.values()))
    score = {s:max(score[s],.01)/(1+.20*vol[s]/max(medvol,1e-12)) for s in ASSETS}
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())),1e-9)
    forecast = {s:float(.01*(score[s]-avg)/sd) for s in ASSETS}
    rebalance_to_weights(weights(score), forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in selected], horizon_days=10)
    last_date = day

