ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
last_decision = None

def cross_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / max(1, len(valid))
    return out

def bounded_weights(scores):
    floor, cap = 0.015, 0.16
    b = {s: max(float(scores[s]), 1e-8) for s in ASSETS}
    w = {s: floor + (1-floor*len(ASSETS))*b[s]/sum(b.values()) for s in ASSETS}
    for _ in range(30):
        high = [s for s in ASSETS if w[s] > cap]
        if not high: break
        excess = sum(w[s]-cap for s in high)
        for s in high: w[s] = cap
        free = [s for s in ASSETS if s not in high]
        den = sum(b[s] for s in free)
        for s in free: w[s] += excess*b[s]/max(den, 1e-12)
    total = sum(w.values())
    return {s: float(w[s]/total) for s in ASSETS}

def vix_state():
    d = get_index_daily_data(symbol="VIX", days=130)
    if d is None or len(d) < 61: return 0.0, False
    c = np.asarray(d.sort_values("date")["close"], dtype=float)
    ref = c[-121:-1]
    med = np.median(ref)
    stress = float(np.clip((c[-1]-med)/max(np.percentile(ref, 90)-med, 1e-9), 0, 1))
    return stress, bool(c[-1] > c[-2] and c[-1] > med)

@register_hook
def strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if len(selected) == 0 or abs(sum(float(f["weight"]) for f in selected)-1.0) > 1e-6:
        return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS): return
    data = {}
    for s in ASSETS:
