    day = str(data[ASSETS[0]].iloc[-1]["date"])[:10]
    if last_decision is not None and np.busday_count(np.datetime64(last_decision), np.datetime64(day)) < 10:
        return
    close = {s: np.asarray(data[s]["close"], dtype=float) for s in ASSETS}
    rets = {s: np.diff(close[s])/np.maximum(close[s][:-1], 1e-12) for s in ASSETS}
    vol = {s: max(float(np.std(rets[s][-20:])), 0.008) for s in ASSETS}
    market = np.mean(np.array([rets[s][-65:] for s in ASSETS]), axis=0)
