    c = np.asarray(d.sort_values("date")["close"], dtype=float)
    ref = c[-121:-1]
    med = np.median(ref)
    stress = float(np.clip((c[-1]-med)/max(np.percentile(ref, 90)-med, 1e-9), 0, 1))
    return stress, bool(c[-1] > c[-2] and c[-1] > med)

@register_hook
