def ranks(values):
    finite = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    n = len(finite)
    for i, (s, _) in enumerate(finite):
        out[s] = (i + 1) / max(n, 1)
    return out

def bounded(base):
    floor, cap = 0.015, 0.16
    x = {s: max(float(base[s]), 1e-9) for s in ASSETS}
    w = {s: floor + (1 - floor*len(ASSETS))*x[s]/sum(x.values()) for s in ASSETS}
    for _ in range(30):
        high = [s for s in ASSETS if w[s] > cap + 1e-12]
        if not high: break
        excess = sum(w[s] - cap for s in high)
        for s in high: w[s] = cap
        free = [s for s in ASSETS if s not in high]
        den = sum(x[s] for s in free)
        for s in free: w[s] += excess*x[s]/max(den, 1e-12)
    z = sum(w.values())
    return {s: float(w[s]/z) for s in ASSETS}

def stress_level():
    d = get_index_daily_data(symbol="VIX", days=130)
