    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good): out[s] = (i + 1) / max(1, len(good))
    return out

def bounded(z):
    floor, cap = .015, .16
    z = {s: max(float(z[s]), 1e-9) for s in ASSETS}
    w = {s: floor + (1 - 15 * floor) * z[s] / sum(z.values()) for s in ASSETS}
